import {readFileSync,readdirSync,lstatSync} from 'node:fs';
import {resolve,relative} from 'node:path';
import {fileURLToPath} from 'node:url';
import {createHash} from 'node:crypto';
import {spawnSync} from 'node:child_process';
import {performance} from 'node:perf_hooks';
import {availableParallelism} from 'node:os';
const root=process.cwd(),own=relative(root,fileURLToPath(import.meta.url)),start=performance.now();
const TOTAL_BUDGET_MS=600000,TEST_BUDGET_MS=480000;
let deadline=start+TOTAL_BUDGET_MS;
const args=Object.fromEntries(process.argv.slice(2).map(s=>{const i=s.indexOf('=');return i<0?[s,true]:[s.slice(0,i),s.slice(i+1)];}));
const fail=m=>{throw new Error('RELEASE HOLD: '+m);};
const hash=(a,b)=>createHash(a).update(b).digest('hex');
function run(cmd,argv,{capture=false,label=cmd,budgetMs=90000}={}){
 const began=performance.now(),remaining=Math.floor(Math.min(deadline-began,budgetMs));if(remaining<=0)fail(`total gate budget exhausted before ${label}`);
 if(!capture)console.log(JSON.stringify({gatePhase:label,event:'start',budgetSeconds:remaining/1000,elapsedSeconds:(began-start)/1000}));
 const r=spawnSync(cmd,argv,{cwd:root,encoding:capture?'utf8':undefined,stdio:capture?'pipe':'inherit',env:Object.fromEntries(Object.entries(process.env).filter(([k])=>k!=='NODE_TEST_CONTEXT')),timeout:remaining,killSignal:'SIGKILL',detached:true,maxBuffer:32*1024*1024});
 if(r.pid){try{process.kill(-r.pid,'SIGKILL');}catch(e){if(e.code!=='ESRCH')throw e;}}
 const elapsed=((performance.now()-began)/1000).toFixed(2);
 if(r.error||r.status!==0){const why=r.error?.code==='ETIMEDOUT'?`TIMEOUT after ${elapsed}s (phase budget ${remaining/1000}s); no release performed; inspect last test and phase logs`:`exit ${r.error?.code||r.signal||r.status} after ${elapsed}s`;fail(`${label}: ${why}`);}
 if(!capture)console.log(JSON.stringify({gatePhase:label,event:'passed',elapsedSeconds:Number(elapsed)}));return r.stdout;
}
function snapshot(tree){
 const head=run('git',['rev-parse','HEAD^{tree}'],{capture:true}).trim();if(head!==tree)fail('HEAD tree is not the explicitly reviewed release');
 const raw=run('git',['ls-tree','-rz',tree],{capture:true}),expected=new Map();
 for(const record of raw.split('\0').filter(Boolean)){const m=/^(100644|100755) blob ([a-f0-9]{40})\t(.+)$/.exec(record);if(!m||m[3].split('/').some(p=>!p||p==='..'||p==='.'||['.git','node_modules','dist'].includes(p)))fail('unsupported source tree entry');expected.set(m[3],{mode:m[1],sha:m[2]});}
 const actual=[];function walk(dir=''){for(const entry of readdirSync(resolve(root,dir),{withFileTypes:true})){if(!dir&&['.git','node_modules','dist'].includes(entry.name))continue;const p=dir?dir+'/'+entry.name:entry.name;if(entry.isDirectory())walk(p);else{if(!entry.isFile())fail('source must be regular file: '+p);actual.push(p);}}}walk();
 if(actual.length!==expected.size||actual.some(p=>!expected.has(p)))fail('unknown or missing source files');
 for(const p of actual){const info=lstatSync(resolve(root,p));if(info.size>128*1024*1024)fail('oversized source: '+p);const bytes=readFileSync(resolve(root,p)),e=expected.get(p),blob=hash('sha1',Buffer.concat([Buffer.from(`blob ${bytes.length}\0`),bytes]));if(blob!==e.sha||((info.mode&0o111)?'100755':'100644')!==e.mode)fail('source bytes/mode changed: '+p);}
 return actual.sort();
}
try{
 if(Object.keys(args).some(k=>!['--gate-sha256','--expect-tree','--verify-only','--budget-ms'].includes(k)))fail('unknown gate argument');
 if(!/^[a-f0-9]{64}$/.test(args['--gate-sha256']||'')||hash('sha256',readFileSync(fileURLToPath(import.meta.url)))!==args['--gate-sha256'])fail('external gate SHA-256 pin missing or mismatched');
 if(!/^[a-f0-9]{40}$/.test(args['--expect-tree']||''))fail('explicit reviewed Git tree required');
 if(own!=='scripts/pinball-shadow-release-gate.mjs')fail('gate outside admitted location');
 if(args['--budget-ms']!==undefined){const n=Number(args['--budget-ms']);if(!Number.isInteger(n)||n<1||n>TOTAL_BUDGET_MS)fail('budget may only lower the fixed ceiling');deadline=start+n;}
 const files=snapshot(args['--expect-tree']);
 if(args['--verify-only']){console.log(JSON.stringify({verified:true,tree:args['--expect-tree'],files:files.length}));process.exit(0);}
 const patterns=[/^tests\/pinball\/.*\.test\.mjs$/,/^tests\/pinball-.*\.test\.mjs$/,/^tests\/.*counts.*\.test\.mjs$/,/^tests\/leaderboard-.*\.test\.mjs$/,/^tests\/(provenance-session|narrow-hud-layout|word-lamp-visual|overtime-events|overtime-presentation|shadow-workers|shadow-worker-visual|boss-overtime-clock|preview-upload-isolation|catalog-release|fast-hands-cooldown-backend|preview-fast-gate-provenance|shadow-release-provenance)\.test\.mjs$/,/^tests\/fast-hands\/(duck.*|.*input.*|shuttle|records|replay|result-copy|leaderboard.*)\.test\.mjs$/];
 const tests=files.filter(p=>patterns.some(pattern=>pattern.test(p)));
 for(const required of ['tests/pinball-palette-provenance.test.mjs','tests/pinball/office-palette.test.mjs','tests/pinball/space-a.test.mjs','tests/pinball-presentation-provenance.test.mjs','tests/pinball/desktop-gameplay-framing.test.mjs','tests/pinball/audio-session.test.mjs','tests/pinball/mobile-focus.test.mjs','tests/pinball/company-sign-framing.test.mjs','tests/pinball-inner-rail-provenance.test.mjs','tests/pinball/inner-rail.test.mjs','tests/pinball/mobile-ui.test.mjs','tests/pinball/mobile-camera.test.mjs','tests/pinball/window-visibility.test.mjs','tests/provenance-session.test.mjs','tests/pinball-gate-performance-provenance.test.mjs','tests/pinball/render-budget.test.mjs','tests/pinball/lottery-label.test.mjs','tests/pinball/office-routes.test.mjs','tests/pinball/raffle-machine.test.mjs','tests/pinball/route-visual.test.mjs','tests/pinball/word-depth.test.mjs','tests/pinball-open-lanes-provenance.test.mjs','tests/pinball/open-lanes.test.mjs','tests/pinball/open-lanes-rules.test.mjs','tests/pinball/lottery-hud-css.test.mjs','tests/pinball/lottery-hud.test.mjs','tests/pinball/gate-hud.test.mjs','tests/pinball/launcher-rearm.test.mjs','tests/pinball/offer-station-visual.test.mjs','tests/pinball-lottery-provenance.test.mjs','tests/pinball/lr-offer.test.mjs','tests/pinball/lottery-integration.test.mjs','tests/pinball/lottery-events.test.mjs','tests/pinball/lottery-assists.test.mjs','tests/pinball/lottery-render.test.mjs','tests/pinball/lottery-position.test.mjs','tests/pinball-flow-provenance.test.mjs','tests/pinball-flow-scope.test.mjs','tests/pinball/flow-rules.test.mjs','tests/pinball/optional-interaction.test.mjs','tests/pinball/upper-assists.test.mjs','tests/pinball/interaction-offer-ui.test.mjs','tests/narrow-hud-layout.test.mjs','tests/pinball/word-lamps.test.mjs','tests/word-lamp-visual.test.mjs','tests/pinball/overtime-core.test.mjs','tests/pinball/interaction-clock.test.mjs','tests/overtime-events.test.mjs','tests/shadow-workers.test.mjs','tests/shadow-release-provenance.test.mjs'])if(!tests.includes(required))fail('required test absent: '+required);
 console.log(JSON.stringify({releaseTree:args['--expect-tree'],testFiles:tests.length,budgetSeconds:TOTAL_BUDGET_MS/1000,testBudgetSeconds:TEST_BUDGET_MS/1000,testConcurrency:2,availableParallelism:availableParallelism()}));
 run(process.execPath,['--test','--test-concurrency=2',...tests],{label:'complete impact tests',budgetMs:TEST_BUDGET_MS});snapshot(args['--expect-tree']);
 run('npm',['run','build'],{label:'static build'});run(process.execPath,['scripts/verify.mjs'],{label:'output references'});run('npm',['run','check:release','--','--expect=preview'],{label:'preview release preflight'});snapshot(args['--expect-tree']);
 console.log(JSON.stringify({releaseGate:'passed',tree:args['--expect-tree'],elapsedSeconds:(performance.now()-start)/1000}));
}catch(e){console.error(e.message);process.exitCode=1;}

import {readFile,readdir,stat} from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import assert from 'node:assert/strict';
const root=fileURLToPath(new URL('../dist/',import.meta.url));
async function files(dir){const entries=await readdir(dir,{withFileTypes:true});return (await Promise.all(entries.map(item=>item.isDirectory()?files(path.join(dir,item.name)):path.join(dir,item.name)))).flat();}
const paths=await files(root);
let checked=0;
for(const file of paths){
  if(!/\.(html|mjs|css)$/.test(file))continue;
  const source=await readFile(file,'utf8');
  const refs=file.endsWith('.html')?[...source.matchAll(/(?:src|href)="([^"]+)"/g)].map(m=>m[1]):file.endsWith('.mjs')?[...source.matchAll(/(?:from\s*|import\s*)['"](\.[^'"]+)['"]/g)].map(m=>m[1]):[...source.matchAll(/url\(['"]?([^)'"\s]+)['"]?\)/g)].map(m=>m[1]);
  for(const ref of refs){
    if(/^(?:https?:|data:|blob:|mailto:)/.test(ref))continue;
    // This fixed server-side navigation route is checked by fighter-entry-count.test.mjs.
    if(ref==='/api/play-counts/entries/taiwanfighter'&&path.relative(root,file)==='index.html'){checked++;continue;}
    if(ref==='#'){checked++;continue;}
    if(ref.startsWith('#')){assert.ok(new RegExp(`id=["']${ref.slice(1)}["']`).test(source),`Missing anchor ${ref} in ${file}`);checked++;continue;}
    let target=ref.startsWith('/')?path.join(root,ref):path.resolve(path.dirname(file),ref);
    target=target.split(/[?#]/)[0];
    let info;try{info=await stat(target);}catch{throw new Error(`Missing local reference ${ref} from ${path.relative(root,file)}`);}
    if(info.isDirectory())await stat(path.join(target,'index.html'));
    checked++;
  }
}
console.log(`Verified ${checked} local references across ${paths.length} output files. Browser visual/touch QA not performed.`);

import {filterReleased,resolveCatalogChannel} from './release.mjs';
const escape = value => String(value).replace(/[&<>"']/g, char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const fastHandsEntries=new Map([
 ['fast-hands',{href:'/games/fast-hands/?intro=1',image:'/assets/fast-hands-card-v2.webp'}],
 ['fast-hands-catch',{href:'/games/fast-hands/catch.html?intro=1',image:'/games/fast-hands/assets/intro-catch-generated.webp'}],
 ['fast-hands-duel',{href:'/games/fast-hands/duel.html?intro=1',image:'/games/fast-hands/assets/intro-duel-generated.webp'}]
]);
const publicDestinations = new Map(['formosabattle','echosboundary','taiwankart','taiwanfighter','arcadeplatform'].map(id=>[id,`https://${id}.playformosa.workers.dev/`]));
publicDestinations.set('soul10power','https://soul10power.vercel.app/');
function validateExternal(entry,needsImage=false) {
  if(!publicDestinations.has(entry.id)||publicDestinations.get(entry.id)!==entry.href)throw new Error('Expected an approved exact external URL');
  if(needsImage && typeof entry.image!=='string')throw new Error('Expected a local portal image');
  for(const image of [entry.image,entry.logo].filter(Boolean))if(!/^\/assets\/portal-[a-z0-9-]+\.(?:png|webp|jpg|svg)$/.test(image))throw new Error('Expected a local portal image');
}
const portalArrow='<svg class="portal-arrow" viewBox="0 0 20 20" aria-hidden="true" focusable="false"><path d="M5 15 15 5M5 5h10v10"/></svg>';
const externalLink=(entry,label)=>`<a class="button portal-cta" href="${escape(entry.id==='taiwanfighter'?'/api/play-counts/entries/taiwanfighter':entry.href)}" target="_blank" rel="noopener noreferrer" aria-label="${escape(label)}：${escape(entry.title)}（另開新分頁）">${escape(label)} ${portalArrow}</a>`;
function renderExternalGame(entry) {
 return `<article class="portal-card portal-card--${escape(entry.id)}" data-external-id="${escape(entry.id)}"><div class="portal-art"><img src="${escape(entry.image)}" alt="" width="1672" height="941" loading="lazy" decoding="async">${entry.logo?`<img class="portal-game-logo" src="${escape(entry.logo)}" alt="" width="1446" height="1120" loading="lazy" decoding="async">`:''}<span class="portal-art-label">${escape(entry.eyebrow)}</span></div><div class="portal-card-body"><p class="portal-genre">${escape(entry.genre)}</p><h3>${escape(entry.title)}</h3><p class="portal-description">${escape(entry.description)}</p>${entry.id==='taiwanfighter'?'<p class="play-count" title="本功能啟用後，從平台點擊進入武鬥的累計次數；不是遊戲內開局次數" data-play-count="taiwanfighter" aria-live="polite">開玩次數讀取中…</p>':''}<div class="portal-card-bottom"><span class="portal-destination">獨立遊戲網站</span>${externalLink(entry,'前往遊玩')}</div></div></article>`;
}
function renderPlatform(entry) {
 return `<article class="platform-feature" data-external-id="${escape(entry.id)}"><div class="platform-brand"><p class="portal-genre">${escape(entry.brand)} · 小遊戲平台</p><h3>${escape(entry.title)}</h3><span class="platform-brand-line" aria-hidden="true"></span></div><div class="platform-copy"><p>${escape(entry.description)}</p><div class="platform-actions">${externalLink(entry,'前往遊戲平台')}<span class="portal-destination">獨立平台・另開新分頁</span></div></div></article>`;
}
export function renderPage({games,events,minigames=[],externalGames=[],platforms=[]},{channel='production'}={}) {
  resolveCatalogChannel({channel});
  const releasedGames=filterReleased(externalGames,channel),releasedPlatforms=filterReleased(platforms,channel);
  releasedGames.forEach(entry=>validateExternal(entry,true));
  releasedPlatforms.forEach(entry=>validateExternal(entry));
  const externalSections=`${releasedGames.length?`<section class="portal-section" id="big-games" aria-labelledby="big-games-title"><div class="portal-section-heading"><div><p class="eyebrow">INDEPENDENT WORLDS</p><h2 id="big-games-title">大遊戲</h2></div><p class="portal-section-note">${releasedGames.length} 個世界，各自精彩。</p></div><p class="portal-intro">從山海江湖到島嶼街頭，選一個世界，展開你的旅程。</p><p class="portal-external-note">以下遊戲將在新分頁開啟，保留各自的遊戲介面。</p><div class="portal-grid">${releasedGames.map(renderExternalGame).join('')}</div></section>`:''}${releasedPlatforms.length?`<section class="portal-section platform-section" id="platforms" aria-labelledby="platforms-title"><div class="portal-section-heading"><div><p class="eyebrow">MORE WAYS TO PLAY</p><h2 id="platforms-title">還想再玩一款？</h2></div></div>${releasedPlatforms.map(renderPlatform).join('')}</section>`:''}`;
  const available=games.filter(game=>game.status==='available');
  const availableMinigames=minigames.filter(game=>game.status==='available');
  for (const game of [...available,...availableMinigames]) {
    const fastHands=fastHandsEntries.get(game.id);
    if (fastHands) {
      if(game.href!==fastHands.href)throw new Error('Expected the exact Fast Hands entrance');
      if(game.image!==fastHands.image)throw new Error('Expected the matching Fast Hands cover');
    } else {
      if (!/^\/games\/[a-z0-9-]+\/$/.test(game.href)) throw new Error('Expected a local game route');
      if (game.image && !/^\/assets\/[a-z0-9-]+\.(?:svg|png|webp|jpg)$/.test(game.image)) throw new Error('Expected a local card image');
    }
  }
  const nextEvents=events.filter(event=>!available.some(game=>game.event===event));
  const featured=available[0];
  const renderCard=(game,collection)=>`<article class="game-card"><a href="${escape(game.href)}" class="game-thumbnail" tabindex="-1" aria-hidden="true"><img src="${escape(game.image || "/assets/hero-long-jump.png")}"${game.image ? (game.imageStyle==='illustration' ? ' class="game-illustration"' : ' class="game-scene"') : ''} alt="" width="1536" height="1024" loading="lazy"><span>${escape(collection)} · ${escape(game.event)}</span></a><div class="game-info"><p class="game-kicker">${escape(game.kicker || "第一個挑戰，先落地再說。")}</p><h3>${escape(game.title)}</h3><p class="event-label">${escape(game.event)}${game.label ? ` · ${escape(game.label)}` : ""}</p><p class="input-chip"><span aria-hidden="true">⌨ / ☝</span> ${escape(game.input || "鍵盤／觸控")}</p>${['long-jump','hurdles','high-jump','pole-vault','shot-put','discus','sprint-100m','run-400m','run-1500m','javelin','overtime-pinball','reaction-rod','beer-slide','tower-climb','fast-hands','fast-hands-catch','fast-hands-duel','courtesy-contest'].includes(game.id)?`<p class="play-count" title="本功能啟用後累計的開局紀錄" data-play-count="${escape(game.id)}" aria-live="polite">遊玩次數讀取中…</p>`:''}</div><a class="button button-primary game-cta" href="${escape(game.href)}" aria-label="開始挑戰：${escape(game.title)}">開始挑戰 <span aria-hidden="true">↗</span></a></article>`;
  return `<!doctype html>
<html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#fff8e9"><meta name="description" content="島遊無界的小遊戲實驗場。操作不一定專業，跌倒一定精彩。從四肢各有想法開始，挑戰不太正經的十項全能。"><title>島遊無界 PLAYFORMOSA｜小遊戲實驗場</title><link rel="stylesheet" href="/assets/home.css"><link rel="icon" type="image/png" sizes="32x32" href="./assets/app-icons/platform/favicon-32.png"><link rel="icon" type="image/png" sizes="48x48" href="./assets/app-icons/platform/favicon-48.png"><link rel="apple-touch-icon" sizes="180x180" href="./assets/app-icons/platform/apple-touch-icon.png"><link rel="manifest" href="./manifest.webmanifest"><meta name="application-name" content="島遊無界"><meta name="apple-mobile-web-app-title" content="島遊無界"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="mobile-web-app-capable" content="yes"></head>
<body data-catalog-channel="${channel}"${releasedGames.length||releasedPlatforms.length?' class="has-portal"':''}><a class="skip-link" href="#main">跳到主要內容</a>
<div class="page-shell"><header class="site-header"><a class="wordmark" href="/" aria-label="島遊無界 PLAYFORMOSA 首頁"><span>島遊無界</span><small>PLAYFORMOSA</small></a><nav aria-label="主要導覽"><a href="#minigames">小遊戲</a><a href="#decathlon">十項全能</a>${releasedGames.length?'<a href="#big-games">大遊戲</a>':''}${releasedPlatforms.length?'<a href="#platforms">play. one more.</a>':''}<a href="#about">關於</a></nav></header>
<main id="main"><section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><p class="eyebrow">小遊戲，大失控。</p><h1 id="hero-title">操作不一定<span class="underline orange">專業</span>，<br>跌倒一定<span class="underline teal">精彩</span>。</h1><p class="hero-subtitle">島遊無界的小遊戲實驗場</p><div class="hero-actions">${featured ? `<a class="button button-primary" href="${escape(featured.href)}">先跳一場 <span aria-hidden="true">↗</span></a>` : ''}<a class="button button-secondary" href="#games">逛逛遊戲 <span aria-hidden="true">↓</span></a></div></div><div class="hero-art"><div class="art-halo" aria-hidden="true"></div><img src="/assets/hero-long-jump.png" alt="一位手腳各自亂飛的逗趣跳遠選手" width="1536" height="1024" fetchpriority="high"><span class="comic-sticker" aria-hidden="true">四肢各有想法！</span><span class="hero-caption">認真起跳，隨緣著陸。</span></div></section>
<section class="series" id="decathlon" aria-labelledby="series-title"><div class="series-heading"><div><p class="eyebrow">THE VERY UNPROFESSIONAL GAMES</p><h2 id="series-title">十項全能挑戰</h2></div><p class="progress">目前開放 <strong>${available.length}<span> / ${events.length}</span></strong> 項</p></div><div class="series-body"><div id="games" class="game-list">${available.map(game=>renderCard(game,'十項全能')).join('')}</div>${nextEvents.length?`<details class="roadmap"><summary>查看後續項目 <span aria-hidden="true">＋</span></summary><div class="roadmap-content"><p>還有 ${nextEvents.length} 個項目正在暖身。先把這一跳玩明白！</p><ul>${nextEvents.map(event=>`<li><span>${escape(event)}</span><small>尚未開放</small></li>`).join('')}</ul><p class="roadmap-note">後續項目為開發規劃，開放時間未定。</p></div></details>`:''}</div></section>
<section class="series minigames" id="minigames" aria-labelledby="minigames-title"><div class="series-heading"><div><p class="eyebrow">SMALL GAMES, BIG REACTIONS</p><h2 id="minigames-title">小遊戲</h2></div><p class="progress">目前開放 <strong>${availableMinigames.length}</strong> 款</p></div><div class="series-body"><div class="game-list">${availableMinigames.map(game=>renderCard(game,'小遊戲')).join('')}${availableMinigames.length ? '' : '<p class="minigames-empty">更多怪點子，慢慢登場。</p>'}</div></div></section>
${externalSections}
